CREATE OR REPLACE FUNCTION public.can_access_frontdesk_data() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role::text IN ('admin','owner','fo_staff','reception','staff')) $$;
REVOKE ALL ON FUNCTION public.can_access_frontdesk_data() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_access_frontdesk_data() TO authenticated, service_role;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['bookings','booking_items','booking_room_assignments','booking_activities','booking_item_activities','booking_charges','booking_payments','booking_payment_activities','booking_tokens','customers','customer_phones','guest_documents','guest_reviews','cash_transactions','cash_tx_attachments','cash_tx_activities','cash_audit_closes','cash_audit_activities','salary_payments'] LOOP EXECUTE format('CREATE POLICY frontdesk_data_restriction ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (public.can_access_frontdesk_data()) WITH CHECK (public.can_access_frontdesk_data())',t); END LOOP; END $$;